INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(25901, 'Acts 4:6', 'Acts', 4, 6, '&nbsp;مشر اِمام اناس او کائفس، يوحنا او سکندر او ورسره د مشر اِمام د خاندان نور خلق هم هلته وُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25902, 'Acts 4:7', 'Acts', 4, 7, '&nbsp;هغوئ پطروس او يوحنا د هغوئ وړاندې راوستل او تپوسونه يې ترې وکړل چې، ”تاسو په کوم طاقت يا د چا په نوم دا کار کړے دے؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25903, 'Acts 4:8', 'Acts', 4, 8, '&nbsp;بيا پطروس له روحُ القُدس نه معمور شو او هغوئ ته يې ووئيل، ”اے د خلقو حاکمانو او مشرانو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25904, 'Acts 4:9', 'Acts', 4, 9, '&nbsp;کۀ چرې نن زمونږ نه د هغه نېک کار تپوسونه کوئ چې د هغه ګوډ سړى سره مو څۀ کړى دى او دا تپوس کوئ چې هغه څنګه روغ شو،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25905, 'Acts 4:10', 'Acts', 4, 10, '&nbsp;نو په دې پوهه شئ تاسو او د بنى اِسرائيلو ټولو خلقو چې، دا سړے ستاسو په وړاندې د عيسىٰ مسيح ناصرى د نوم په وسيله روغ ولاړ دے، څوک چې تاسو په سولۍ کړو خو خُدائ پاک هغه د مړو نه بيا راژوندے کړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25906, 'Acts 4:11', 'Acts', 4, 11, '&nbsp;دا عيسىٰ ”هغه کاڼے دے چې تاسو ګِلکارانو رد کړے وو او هغه د ګوټ سر کاڼے شو.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25907, 'Acts 4:12', 'Acts', 4, 12, '&nbsp;د بل هيچا په وسيله خلاصون نشته ځکه چې په ټوله دُنيا کښې بل نوم هيچا ته نۀ دے ورکړے شوے چې په هغې مونږ خلاصون ومومو.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25908, 'Acts 4:13', 'Acts', 4, 13, '&nbsp;کله چې دوئ د پطروس او يوحنا زړۀ ورتيا وليدله او دا هم ورته معلومه شوه چې دوئ عام او بې‌علمه خلق وُو، نو هغوئ حېران شول او وې پېژندل چې دا د عيسىٰ ملګرى وُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25909, 'Acts 4:14', 'Acts', 4, 14, '&nbsp;خو چې هغوئ هغه سړے روغ جوړ د دوئ سره ولاړ وليدلو نو هغوئ سره د دې خلاف د وئيلو هيڅ نۀ وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25910, 'Acts 4:15', 'Acts', 4, 15, '&nbsp;نو هغوئ ورته حُکم ورکړو چې د جرګې نه وځئ او بيا يې په خپل مينځ کښې په دې صلاح مشوره شروع کړه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25911, 'Acts 4:16', 'Acts', 4, 16, '&nbsp;هغوئ ووئيل چې، ”مونږ دې سړو سره څۀ وکړو؟ ځکه چې په يروشلم کښې هر چا ته پته ده چې يوه نا آشنا معجزه دوئ کړې ده او مونږ د دې نه اِنکار نۀ شو کولے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25912, 'Acts 4:17', 'Acts', 4, 17, '&nbsp;خو د دې دپاره چې په خلقو کښې دا خبره نوره خوره نۀ شى، مونږ ته په کار دى چې دې سړو ته خبردارے ورکړو چې نور به په دغه نوم د هيچا سره خبرې نۀ کوى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25913, 'Acts 4:18', 'Acts', 4, 18, '&nbsp;بيا يې هغوئ دننه راوبلل او حُکم يې ورکړو چې، ”د عيسىٰ په نوم به هيڅ قسم خبرې يا تعليم نۀ ورکوئ.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25914, 'Acts 4:19', 'Acts', 4, 19, '&nbsp;خو پطروس او يوحنا هغوئ ته په جواب کښې ووئيل، ”تاسو په خپله اِنصاف وکړئ چې ولې د خُدائ پاک په نظر کښې دا خبره ټيک ده چې مونږ د هغۀ په ځائ ستاسو ومنو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25915, 'Acts 4:20', 'Acts', 4, 20, '&nbsp;مونږ د هغه څۀ په حقله د وئيلو نه نۀ شُو منع کېدے څۀ چې مونږ ليدلى او اورېدلى دى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25916, 'Acts 4:21', 'Acts', 4, 21, '&nbsp;په دوېم ځل يې سخت خبردارے ورکړو او پرې يې ښودل. هغوئ دا فېصله ونۀ کړے شوه چې دوئ ته څنګه سزا ورکړى، ځکه چې ټولو خلقو په هغه شوى کار د خُدائ پاک ثنا وئيله.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25917, 'Acts 4:22', 'Acts', 4, 22, '&nbsp;نو چې کوم سړى ته په مُعجزانه طور شفا مِلاو شوې وه د هغۀ عُمر د څلوېښتو کالو نه زيات وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25918, 'Acts 4:23', 'Acts', 4, 23, '&nbsp;کله چې پطروس او يوحنا آزاد کړے شول نو هغوئ خپلو ملګرو له لاړل او هغه هر څۀ يې ورته ووئيل څۀ چې مشرانو اِمامانو او مشرانو هغوئ ته وئيلى وُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25919, 'Acts 4:24', 'Acts', 4, 24, '&nbsp;کله چې هغوئ دا واورېدل نو هغوئ په جمع په اوچت آواز خُدائ پاک ته دُعا وکړه او وئ وئيل، ”اے مالِکه، د زمکې آسمان او سمندر او هر څۀ چې په دې کښې دى د هغې خالقه،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25920, 'Acts 4:25', 'Acts', 4, 25, '&nbsp;دا تا د روحُ القُدس په وسيله زمونږ د نيکۀ داؤد په خولۀ فرمائيلى وُو چې، ”قومونه ولې په قهر شول او اُمتونه ولې بې‌فائدې سازشونه کوى؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25921, 'Acts 4:26', 'Acts', 4, 26, '&nbsp;د دُنيا بادشاهان راپورته شول او حاکمان د مالِک خلاف او د هغۀ د مسيح په خلاف يو ځائ شول.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25922, 'Acts 4:27', 'Acts', 4, 27, '&nbsp;په حقيقت کښې په دې ښار کښې هيروديس او پنطوس پيلاطوس دواړه د غېر يهودى قومونو او د بنى اِسرائيلو خلقو سره ستا د پاک خادِم عيسىٰ چې تا مسح کړے دے، خلاف يو ځائ شول،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25923, 'Acts 4:28', 'Acts', 4, 28, '&nbsp;چې هغه هر څۀ وکړى کوم چې ستا د لاس لاندې او ستا په حُکم د مخکښې نه مقرر شوى وُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25924, 'Acts 4:29', 'Acts', 4, 29, '&nbsp;او اوس اے مالِکه، د هغوئ دهمکيانو ته غور وکړه او خپلو خادِمانو ته پوره زړۀ ورتيا ورکړه چې ستا کلام بيان کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25925, 'Acts 4:30', 'Acts', 4, 30, '&nbsp;خپل لاس راوږد کړه چې شفا ورکړى او معجزې نښې او عجيبه کارونه ستا د پاک خادِم عيسىٰ د نوم په وسيله وکړى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25926, 'Acts 4:31', 'Acts', 4, 31, '&nbsp;کله چې هغوئ دُعا وکړه نو په کوم کور کښې چې هغوئ راغونډ شوى وُو، هغه وجړقېدلو او هغوئ ټول په روحُ القُدس معمور شول او د خُدائ پاک کلام يې په زړۀ ورتيا بيان کړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25927, 'Acts 4:32', 'Acts', 4, 32, '&nbsp;ټول ايمانداران په يو زړۀ وو او چا هم دا دعوىٰ نۀ کوله چې دا د هغوئ ملکيت دے بلکې هغوئ سره چې څۀ هم وو هغه يې شريک کړل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25928, 'Acts 4:33', 'Acts', 4, 33, '&nbsp;په ډېر لوئ قدرت سره رسولانو د مالِک عيسىٰ د بيا راژوندى کېدو ګواهى ورکوله او په هغوئ ټولو باندې د خُدائ پاک لوئ برکت وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25929, 'Acts 4:34', 'Acts', 4, 34, '&nbsp;په هغوئ کښې يو کس هم حاجتمند پاتې نۀ وو ځکه چې د چا سره چې کور يا جائيداد وو هغه يې خرڅ کړل او د هغې قيمت يې راوړلو،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25930, 'Acts 4:35', 'Acts', 4, 35, '&nbsp;او د رسولانو په حضور کښې به يې پېش کولو. بيا هغه پېسې به يې هر هغه چا ته ورکولې د چا به چې ضرورت وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25931, 'Acts 4:36', 'Acts', 4, 36, '&nbsp;نو يوسف نومې يو ليوى وو چې د قبرص اوسېدونکے وو او رسولانو به ورته برنباس وئيلو چې معنىٰ يې ډاډ ورکوونکے دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25932, 'Acts 4:37', 'Acts', 4, 37, '&nbsp;او هغۀ خپل څۀ جائيداد خرڅ کړو. او د هغې قيمت يې راوړو او هغه يې د رسولانو په حضور کښې پېش کړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25933, 'Acts 5:1', 'Acts', 5, 1, '&nbsp;خو يو بل سړے وو چې نوم يې حنانياس وو، هغۀ د خپلې ښځې سفيره سره يو ځائ څۀ جائيداد خرڅ کړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25934, 'Acts 5:2', 'Acts', 5, 2, '&nbsp;د خپلې ښځې په صلاح يې د قيمت څۀ حِصه د ځان سره وساتله او څۀ يې راوړه او د رسولانو په حضور کښې يې پېش کړله.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25935, 'Acts 5:3', 'Acts', 5, 3, '&nbsp;خو پطروس ووئيل چې، ”حنانياس، دا شېطان درباندې څنګه غالب شو چې تۀ روحُ القُدس ته دروغ وائې او د زمکې د قيمت څۀ حِصه دې ځان ته پرېښوده؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25936, 'Acts 5:4', 'Acts', 5, 4, '&nbsp;ترڅو چې درسره وه دا ستا نۀ وه څۀ؟ هر کله چې دا خرڅه شوه نو پېسې ستا نۀ وې څۀ؟ نو تا دا سوچ څنګه وکړو؟ تا نۀ صرف خلقو ته بلکې خُدائ پاک ته دې دروغ ووئيل.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25937, 'Acts 5:5', 'Acts', 5, 5, '&nbsp;کله چې حنانياس دا خبرې واورېدلې نو هغه سر د لاندې راپرېوتو او په ټکى مړ شو او چا چې دا خبره واورېدله نو هغوئ ټول يرې واخستل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25938, 'Acts 5:6', 'Acts', 5, 6, '&nbsp;بيا څو ځوانان راپاڅېدل د هغۀ لاش يې کفن کړو، او د هغه ځائ نه يې بهر يوړو او دفن يې کړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25939, 'Acts 5:7', 'Acts', 5, 7, '&nbsp;بيا درې ګينټې پس د هغۀ ښځه راغله، هغې ته پته نۀ وه چې څۀ شوى وُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25940, 'Acts 5:8', 'Acts', 5, 8, '&nbsp;پطروس هغې نه تپوس وکړو چې، ”ما ته ووايه، تا او حنانياس ته د زمکې هم دومره قيمت مِلاو شوے وو؟“ هغې ووئيل چې، ”آو، هم دغه قيمت ملا شوے وو.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25941, 'Acts 5:9', 'Acts', 5, 9, '&nbsp;بيا پطروس هغې ته ووئيل، ”نو بيا تاسو دواړو ولې د مالِک روح وآزمائيلو؟ ګوره هغه خلق په دروازه کښې ولاړ دى چا چې ستا خاوند ښخ کړو او هغوئ به اوس تا هم بهر يوسى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25942, 'Acts 5:10', 'Acts', 5, 10, '&nbsp;هم هغه وخت هغه د هغۀ په پښو کښې سر د لاندې راپرېوتله او په ټکى مړه شوه. بيا ځوانان دننه راغلل هغوئ هغه مړه وليده نو هغوئ هغه بهر يوړه او د خاوند په خوا کښې يې ښخه کړه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25943, 'Acts 5:11', 'Acts', 5, 11, '&nbsp;هر چا چې د دې واقعې په حقله واورېدل نو په ټولو خلقو او په جماعت کښې سخته يره خوره شوه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25944, 'Acts 5:12', 'Acts', 5, 12, '&nbsp;اوس ډيرې معجزې او عجيبه کارونه د خلقو په مينځ کښې د رسولانو په وسيله وشو. او ټول ايمانداران به د سليمان په ډيوډۍ کښې راغونډېدل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25945, 'Acts 5:13', 'Acts', 5, 13, '&nbsp;نو چا هم د هغوئ سره د ګډون کولو جرأت نۀ کولو، اګر چې خلقو د هغوئ ډېر عزت کولو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25946, 'Acts 5:14', 'Acts', 5, 14, '&nbsp;سره د دې ډېرو سړو او ښځو په مالِک ايمان راوړو او د هغوئ په ډله کښې شامل شول.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25947, 'Acts 5:15', 'Acts', 5, 15, '&nbsp;هم دغه شان خلقو بيماران په کټونو او درو باندې واچول او بهر کوڅو ته يې راوويستل په دې نيت چې کله پطروس په دې لاره تېريږى چې د هغۀ سورے په هغوئ پرېوځى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25948, 'Acts 5:16', 'Acts', 5, 16, '&nbsp;د خوا او شا کلو نه به ډېر خلق د يروشلم ښار ته راتلل، او خپل بيماران او هغه خلق به يې راوستل چې پيريانو به نيولى وُو، او هغوئ ټولو به شفا موندله.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
